CREATE DATABASE IF NOT EXISTS sisableng_ops CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE sisableng_ops;
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, display_name VARCHAR(120) NOT NULL DEFAULT 'Operator', role ENUM('admin','operator','viewer') NOT NULL DEFAULT 'operator', is_active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE input_records (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, plate VARCHAR(16) NOT NULL, input_payload JSON NULL, validation_status ENUM('pending','valid','invalid','review') NOT NULL DEFAULT 'pending', created_by BIGINT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(plate), INDEX(validation_status), FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE controller_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, plate VARCHAR(16) NOT NULL, action_type ENUM('verifikasi_nopol','reset_biasa_perorangan','reset_gantung_perorangan','reset_perusahaan','buka_blokir_permanen','blokir_permanen','hapus_perorangan','hapus_perusahaan') NOT NULL, reason VARCHAR(500) NULL, status ENUM('pending_review','approved','rejected','completed','failed') NOT NULL DEFAULT 'pending_review', requested_by BIGINT UNSIGNED NULL, reviewed_by BIGINT UNSIGNED NULL, reviewed_at TIMESTAMP NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(plate), INDEX(status), FOREIGN KEY(requested_by) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY(reviewed_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE api_config (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, service_name VARCHAR(100) NOT NULL UNIQUE, is_enabled TINYINT(1) NOT NULL DEFAULT 0, secret_ref VARCHAR(255) NULL COMMENT 'Pointer to server-side secret store; never plaintext key', updated_by BIGINT UNSIGNED NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(updated_by) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE activity_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NULL, event_type VARCHAR(100) NOT NULL, event_detail JSON NULL, ip_hash CHAR(64) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(created_at), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE security_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username_attempt VARCHAR(80) NULL, event_type VARCHAR(100) NOT NULL, success TINYINT(1) NOT NULL DEFAULT 0, ip_hash CHAR(64) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(created_at)) ENGINE=InnoDB;
